def maxRectangleArea(points: List[List[int]]) -> int:
    # Convert points to a set for O(1) lookup
    point_set = set((x, y) for x, y in points)

    # Get all unique x and y coordinates
    xs = sorted(set(x for x, y in points))
    ys = sorted(set(y for x, y in points))

    max_area = -1

    # Try all pairs of x coordinates and y coordinates
    for i in range(len(xs)):
        for j in range(i + 1, len(xs)):
            x1, x2 = xs[i], xs[j]
            for k in range(len(ys)):
                for l in range(k + 1, len(ys)):
                    y1, y2 = ys[k], ys[l]

                    # Check if all four corners exist
                    corners = [(x1, y1), (x1, y2), (x2, y1), (x2, y2)]
                    if all(c in point_set for c in corners):
                        # Check if there are any other points inside or on the border
