from typing import List
from collections import deque

def findSafeWalk(grid: List[List[int]], health: int):
    m, n = len(grid), len(grid[0])
    # BFS/DFS tracking max health remaining at each cell
    # health_remaining[i][j] = max health left when arriving at (i,j)
    dp = [[-1] * n for _ in range(m)]
    dp[0][0] = health - grid[0][0]
    if dp[0][0] <= 0:
        return False
    if m == 1 and n == 1:
        return dp[0][0] >= 1

    q = deque([(0, 0)])
    while q:
        i, j = q.popleft()
        for di, dj in [(0,1),(0,-1),(1,0),(-1,0)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < m and 0 <= nj < n:
                new_health = dp[i][j] - grid[ni][nj]
                if new_health > dp[ni][nj]:
                    dp[ni][nj] = new_health
                    if new_health > 0:
                        q.append((ni, nj))
    return dp[m-1][n-1] >= 1
