from typing import List

def maxScore(n: int, k: int, stayScore: List[List[int]], travelScore: List[List[int]]):
    # dp[city] = max score ending at city after processing all days so far
    # Initialize: tourist can start at any city, so dp starts as 0 for all cities
    dp = [0] * n

    for day in range(k):
        new_dp = [0] * n
        for dest in range(n):
            best = -1
            # Option 1: stay in dest
            best = max(best, dp[dest] + stayScore[day][dest])
            # Option 2: move from any other city curr to dest
            for curr in range(n):
                if curr != dest:
                    val = dp[curr] + travelScore[curr][dest]
                    if val > best:
                        best = val
            new_dp[dest] = best
        dp = new_dp

    return max(dp)
