from typing import List

def longestSubsequence(nums: List[int]):
    n = len(nums)
    # dp[i][d] = longest subsequence ending at index i with last absolute difference being d
    # d can be 0 to 300 (since nums[i] is 1 to 300, max diff is 299)
    MAX_D = 300
    dp = [[0] * (MAX_D + 1) for _ in range(n)]

    for i in range(n):
        dp[i][0] = 1  # subsequence of length 1 has no diff, but we need to handle this

    for i in range(1, n):
        for d in range(MAX_D + 1):
            # Try to extend a subsequence ending at some j < i with last diff >= d
            diff = abs(nums[i] - nums[i-1])  # no, we need to check all j
            pass

    # Let's redo: for each i, for each possible last diff d, find best j < i
    # such that the diff between nums[j] and nums[i] is d, and the previous diff at j was >= d

    dp = [[0] * (MAX_D + 1) for _ in range(n)]

    for i in range(n):
        dp[i][0] = 1

    for i in range(1, n):
        for d in range(1, MAX_D + 1):
            # Check if nums[i] - nums[j] or nums[j] - nums[i] equals d for some j < i
            # We need: abs(nums[i] - nums[j]) == d, and dp[j][prev_d] >= 1 where prev_d >= d
            # Actually, dp[j][x] means subsequence ending at j with last diff x
            # We want to find max dp[j][x] where x >= d and abs(nums[i]-nums[j]) == d

            # Since nums values are small (1-300), we can iterate j
            best = 0
            for j in range(i):
                diff = abs(nums[i] - nums[j])
                if diff == d:
                    # Find max dp[j][x] for x >= d
                    for x in range(d, MAX_D + 1):
                        if dp[j][x] > best:
                            best = dp[j][x]
                    # Also consider starting new subsequence (length 1 at j, no prior diff)
                    if dp[j][0] > best:
                        best = dp[j][0]
            dp[i][d] = best + 1 if best > 0 else 1

    ans = 0
    for i in range(n):
        for d in range(MAX_D + 1):
            if dp[i][d] > ans:
                ans = dp[i][d]

    return ans
